#include <stdio.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    long long* data;
    size_t len;
} Array_i64;

bool arrEquals(Array_i64 first, Array_i64 second) {
    if (first.len != second.len) {
        return false;
    }
    for (size_t i = 0; i < first.len; i++) {
        if (first.data[i] != second.data[i]) {
            return false;
        }
    }
    return true;
}

void printBool(bool b) {
    printf(b ? "true\n" : "false\n");
}

int main() {
    // Test 1: equal arrays
    long long d1[] = {1, 2, 3};
    long long d2[] = {1, 2, 3};
    Array_i64 a1 = {d1, 3};
    Array_i64 a2 = {d2, 3};
    printBool(arrEquals(a1, a2));

    // Test 2: different lengths
    long long d3[] = {1, 2};
    Array_i64 a3 = {d3, 2};
    printBool(arrEquals(a1, a3));

    // Test 3: empty arrays
    long long* d4 = NULL;
    long long* d5 = NULL;
    Array_i64 a4 = {d4, 0};
    Array_i64 a5 = {d5, 0};
    printBool(arrEquals(a4, a5));

    // Test 4: same length, different elements
    long long d6[] = {1, 2, 4};
    Array_i64 a6 = {d6, 3};
    printBool(arrEquals(a1, a6));

    // Test 5: negative values
    long long d7[] = {-5, 0, 7};
    long long d8[] = {-5, 0, 7};
    Array_i64 a7 = {d7, 3};
    Array_i64 a8 = {d8, 3};
    printBool(arrEquals(a7, a8));

    return 0;
}

