import java.util.Arrays;

public class Solution {
    public static boolean arrEquals(long[] first, long[] second) {
        if (first == null || second == null) {
            return false;
        }
        if (first.length != second.length) {
            return false;
        }
        for (int i = 0; i < first.length; i++) {
            if (first[i] != second[i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        // Test case 1: equal arrays
        long[] a1 = {1, 2, 3};
        long[] b1 = {1, 2, 3};
        System.out.println(arrEquals(a1, b1));

        // Test case 2: different lengths
        long[] a2 = {1, 2, 3};
        long[] b2 = {1, 2};
        System.out.println(arrEquals(a2, b2));

        // Test case 3: empty arrays
        long[] a3 = {};
        long[] b3 = {};
        System.out.println(arrEquals(a3, b3));

        // Test case 4: arrays with negative values
        long[] a4 = {-5, 0, 7};
        long[] b4 = {-5, 0, 7};
        System.out.println(arrEquals(a4, b4));

        // Test case 5: same length but different elements
        long[] a5 = {10, 20, 30};
        long[] b5 = {10, 25, 30};
        System.out.println(arrEquals(a5, b5));
    }
}
